import { describe, it, expect, vi } from 'vitest'
import { setSessionCookie } from './cookies'

const set = vi.fn()
vi.mock('next/headers', () => ({ cookies: () => ({ set }) }))

describe('setSessionCookie', () => {
  it('scopes the cookie to the whole site', () => {
    setSessionCookie('abc')
    expect(set).toHaveBeenCalledWith('session_token', 'abc', expect.objectContaining({ path: '/', sameSite: 'lax' }))
  })
})

