package http

import (
	"encoding/base64"
	"encoding/json"
	"time"
)

type cursor struct {
	CreatedAt time.Time `json:"t"`
	ID        int64     `json:"i"`
}

func encodeCursor(c cursor) string {
	b, _ := json.Marshal(c)
	return base64.RawURLEncoding.EncodeToString(b)
}
